package localchat;
import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import java.util.*;import java.util.List;import javax.swing.*;
/** Synthetic providers only: stable rename, isolated deletion, persistence and compact UI. */
public final class ProviderManagementTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static LocalChat window(Path home)throws Exception{System.setProperty("localchat.home",home.toString());var ctor=LocalChat.class.getDeclaredConstructor();ctor.setAccessible(true);return ctor.newInstance();}
 static Map<String,String> subtree(Properties config,String prefix){Map<String,String> out=new TreeMap<>();for(String key:config.stringPropertyNames())if(key.startsWith(prefix+"."))out.put(key,config.getProperty(key));return out;}
 static void primitives(){Properties config=new Properties();SavedProviders.Entry a=SavedProviders.save(config,"A",Provider.CUSTOM,"https://a.invalid/v1","fake-a","model-a"),b=SavedProviders.save(config,"B",Provider.ANTHROPIC,"https://b.invalid/v1","fake-b","model-b");config.setProperty(a.prefix()+".models","[\"model-a\"]");ModelFavorites.toggle(config,a.prefix(),"https://a.invalid/v1","model-a");config.setProperty("default.providerPreset",a.id());config.setProperty("default.provider","CUSTOM");config.setProperty("default.model","model-a");config.setProperty("default.url","https://a.invalid/v1");config.setProperty("default.workdir","preserved");var before=subtree(config,a.prefix());var renamed=SavedProviders.rename(config,a,"New A");check(renamed.id().equals(a.id()),"rename keeps stable identity");var after=subtree(config,a.prefix());after.put(a.prefix()+".name","A");check(before.equals(after),"rename preserves key, route, models and favorites");check(config.getProperty("default.providerPreset").equals(a.id()),"default association survives rename");
  for(String bad:List.of("B"," ","<html>","x".repeat(81))){Properties snapshot=new Properties();snapshot.putAll(config);try{SavedProviders.rename(config,renamed,bad);throw new AssertionError("bad rename accepted");}catch(IllegalArgumentException expected){check(config.equals(snapshot),"invalid/colliding name changes nothing");}}
  var other=subtree(config,b.prefix());SavedProviders.remove(config,renamed);check(subtree(config,a.prefix()).isEmpty()&&subtree(config,b.prefix()).equals(other),"deletion removes only selected provider including credentials/favorites");check(!config.containsKey("default.providerPreset")&&!config.containsKey("default.model")&&"preserved".equals(config.getProperty("default.workdir")),"deleted default unlinked without changing operational defaults");var fresh=SavedProviders.save(config,"New A",Provider.CUSTOM,"https://a.invalid/v1","replacement","model-a");check(!fresh.id().equals(a.id()),"readding same label does not resurrect deleted identity");
 }
 public static void main(String[] args)throws Exception{
  primitives();Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  try(var server=new ProviderTest.Catalog()){
   FeatureTest.edt(()->{
    LocalChat app=AttachmentTest.window(home,server.url());ProviderTest.set(app,Provider.CUSTOM,server.url(),"model-a","fixture-a");FeatureTest.call(app,"saveNamedProvider",new Class<?>[]{String.class},"Provider A");SavedProviders.Entry a=FeatureTest.field(app,"shownSelection");
    var history=FeatureTest.<List<ChatClient.Message>>field(app,"history");history.add(ChatClient.Message.user("Keep this project history"));FeatureTest.call(app,"ensureSession",new Class<?>[]{});FeatureTest.call(app,"saveConversation",new Class<?>[]{});Path chat=FeatureTest.field(app,"conversationFile");byte[] chatBefore=Files.readAllBytes(chat);
    Properties config=FeatureTest.field(app,"config");ModelFavorites.toggle(config,a.prefix(),server.url(),"model-a");config.setProperty(a.prefix()+".catalog","[]");
    ProviderTest.set(app,Provider.CUSTOM,"http://127.0.0.1:2/v1","model-b","fixture-b");FeatureTest.call(app,"saveNamedProvider",new Class<?>[]{String.class},"Provider B");SavedProviders.Entry b=FeatureTest.field(app,"shownSelection");((JComboBox<Object>)FeatureTest.field(app,"providerBox")).setSelectedItem(a);FeatureTest.call(app,"saveDefaults",new Class<?>[]{});
    AttachmentTest.input(app).setText("unsent draft");FeatureTest.call(app,"renameNamedProvider",new Class<?>[]{String.class},"Renamed A");SavedProviders.Entry renamed=FeatureTest.field(app,"shownSelection");check(renamed.id().equals(a.id())&&renamed.name().equals("Renamed A"),"UI rename keeps selected identity");check(new String(((JPasswordField)FeatureTest.field(app,"keyField")).getPassword()).equals("fixture-a"),"rename keeps matching key");check(ModelFavorites.contains(config,a.prefix(),server.url(),"model-a"),"favorites remain associated");check(AttachmentTest.input(app).getText().equals("unsent draft"),"rename preserves draft");
    byte[] savedChat=Files.readAllBytes(chat);check(!new String(savedChat,java.nio.charset.StandardCharsets.UTF_8).contains("fixture-a"),"conversation never contains API key");check(FeatureTest.<List<ChatClient.Message>>field(app,"history").get(0).content.contains("Keep this"),"rename does not change message history");
    try{FeatureTest.call(app,"renameNamedProvider",new Class<?>[]{String.class},"Provider B");throw new AssertionError("collision accepted");}catch(java.lang.reflect.InvocationTargetException expected){check(expected.getCause() instanceof IllegalArgumentException,"UI rejects collision without overwriting B");}
    app.dispose();app=window(home);check(((SavedProviders.Entry)FeatureTest.field(app,"shownSelection")).name().equals("Renamed A"),"restart resolves renamed default by stable identity");config=FeatureTest.field(app,"config");
    for(int locale=0;locale<I18n.CODES.length;locale++)for(int theme=0;theme<2;theme++){
      ((JComboBox<?>)FeatureTest.field(app,"languageBox")).setSelectedIndex(locale);((JComboBox<?>)FeatureTest.field(app,"themeBox")).setSelectedIndex(theme);JButton plus=FeatureTest.field(app,"saveProviderButton"),more=FeatureTest.field(app,"manageProviderButton");check(plus.getText().isEmpty()&&plus.getIcon()!=null&&plus.getPreferredSize().width<=32,"compact plus in every locale/theme");check(more.getText().isEmpty()&&more.getIcon()!=null&&more.getPreferredSize().width<=32,"compact management menu");check(plus.getToolTipText().equals(I18n.text("Adauga furnizor")),"localized accessible add action");JPopupMenu menu=(JPopupMenu)FeatureTest.call(app,"providerMenu",new Class<?>[]{});check(menu.getComponentCount()==3&&Arrays.stream(menu.getComponents()).allMatch(c->c.isEnabled()),"all actions available for saved provider");
      if(locale==1){app.setSize(1400,950);app.addNotify();app.validate();Component controls=plus.getParent().getParent();BufferedImage image=new BufferedImage(Math.max(1,controls.getWidth()),Math.max(1,controls.getHeight()),BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();controls.printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",home.resolve(theme==1?"providers-dark.png":"providers-light.png").toFile());}
    }
    I18n.setLanguage("ro");Path settings=FeatureTest.field(app,"configFile"),backup=settings.resolveSibling("settings-preserved.properties");Files.move(settings,backup);Files.createDirectory(settings);
    try{FeatureTest.call(app,"renameNamedProvider",new Class<?>[]{String.class},"Must not persist");throw new AssertionError("failed write accepted");}catch(java.lang.reflect.InvocationTargetException expected){check("Renamed A".equals(config.getProperty(a.prefix()+".name")),"failed settings write does not apply rename");}
    try{FeatureTest.call(app,"deleteNamedProvider",new Class<?>[]{});throw new AssertionError("failed delete accepted");}catch(java.lang.reflect.InvocationTargetException expected){check(SavedProviders.present(config,a),"failed write does not remove provider");}Files.delete(settings);Files.move(backup,settings);
    var beforeB=subtree(config,b.prefix());config.setProperty(Provider.CUSTOM.id()+".key","builtin-only");FeatureTest.call(app,"deleteNamedProvider",new Class<?>[]{});check(subtree(config,a.prefix()).isEmpty()&&subtree(config,b.prefix()).equals(beforeB),"UI deletion isolates provider data");check(FeatureTest.field(app,"shownSelection")==Provider.CUSTOM,"deleted selection switches to available protocol");check(!config.containsKey("default.providerPreset"),"deleted default no longer selected at startup");check(Arrays.equals(savedChat,Files.readAllBytes(chat)),"delete leaves archived conversation untouched");FeatureTest.call(app,"saveConfig",new Class<?>[]{});check(subtree(config,a.prefix()).isEmpty(),"later save does not resurrect removed key");
    app.dispose();app=window(home);FeatureTest.command(app,"/switch "+Conversations.shortId(chat));Object missing=FeatureTest.field(app,"shownSelection");check(missing instanceof SavedProviders.Entry entry&&entry.id().equals(a.id()),"old chat retains unavailable provider identity");check(((JPasswordField)FeatureTest.field(app,"keyField")).getPassword().length==0,"old chat never borrows another provider credential");
    int calls=server.requests.size();AttachmentTest.input(app).setText("Do not send this without a provider");FeatureTest.call(app,"send",new Class<?>[]{});FeatureTest.call(app,"inspectModel",new Class<?>[]{});FeatureTest.call(app,"loadModels",new Class<?>[]{});FeatureTest.call(app,"autoInspectModel",new Class<?>[]{});FeatureTest.call(app,"saveConfig",new Class<?>[]{});check(server.requests.size()==calls,"missing provider cannot start inference, metadata or model loading");check(AttachmentTest.input(app).getText().startsWith("Do not send"),"blocked send keeps draft");config=FeatureTest.field(app,"config");check(subtree(config,a.prefix()).isEmpty()&&"builtin-only".equals(config.getProperty(Provider.CUSTOM.id()+".key")),"resuming missing provider cannot recreate keys or overwrite built-in credentials");
    ((JComboBox<Object>)FeatureTest.field(app,"providerBox")).setSelectedItem(Provider.CUSTOM);JPopupMenu menu=(JPopupMenu)FeatureTest.call(app,"providerMenu",new Class<?>[]{});check(Arrays.stream(menu.getComponents()).noneMatch(c->c.isEnabled()),"built-in protocol templates cannot be renamed/deleted");check(subtree(config,a.prefix()).isEmpty(),"leaving unavailable placeholder remains safe");app.dispose();
   });
  }finally{FeatureTest.edt(()->{for(Window window:Window.getWindows())window.dispose();});}
  System.out.println("PASS: "+checks+" provider management checks; stable rename, exact deletion, failed writes, preserved chats, unavailable-provider isolation, compact controls and six languages/themes");System.exit(0);
 }
}
